1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	// ---------------------------------------------------------------------------
42	// Shared arithmetic — used by both the premium and the claim side.
43	// ---------------------------------------------------------------------------
44	
45	// Percentages MUST go through this helper. Multiplying first and dividing by
46	// 100 afterwards keeps the arithmetic drift-free; the tempting `amount * 0.5`
47	// (or `* 1.1`) introduces binary-fraction error — 100 * 1.1 yields
48	// 110.00000000000001 — and since the spec rounds premiums UP at the very end
49	// that drift becomes a whole extra G.
50	const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;
51	
52	// Money adds up the same way everywhere in this module — over items, over
53	// damages, over per-type groups. Naming the fold once keeps each call site
54	// about WHAT is being totalled rather than re-deriving how a sum is spelled.
55	const sumOf = <T>(values: T[], amountOf: (value: T) => number): number =>
56	  values.reduce((total, value) => total + amountOf(value), 0);
57	
58	// Each item-level surcharge is "a percentage of this item's base premium, or
59	// nothing at all", so the condition is the only part that varies.
60	const percentOfWhen = (applies: boolean, amount: number, percent: number): number =>
61	  applies ? percentOf(amount, percent) : 0;
62	
63	// The MHPCO rounds in its own favour. That is ONE rule, but "its favour" points
64	// in opposite directions on the two sides of the business: a premium is money
65	// coming in, so a fraction rounds UP; a payout is money going out, so a fraction
66	// rounds DOWN. Naming both halves keeps the rule greppable and stops either call
67	// site from reading as an arbitrary choice of Math.ceil over Math.floor.
68	// They are deliberately two functions rather than one with a direction flag:
69	// `roundInMhpcosFavour(total, UP)` would hide at the call site exactly what the
70	// reader came there to learn.
71	const roundPremiumInMhpcosFavour = (amount: number): number => Math.ceil(amount);
72	const roundPayoutInMhpcosFavour = (amount: number): number => Math.floor(amount);
73	
74	// ---------------------------------------------------------------------------
75	// Premium side — quoting a policy.
76	// ---------------------------------------------------------------------------
77	
78	const PROCESSING_FEE = 5;
79	
80	const FIRST_INSURANCE_PERCENT = 10;
81	
82	const BASE_PREMIUMS: Record<string, number> = {
83	  sword: 100,
84	  amulet: 60,
85	  staff: 80,
86	  potion: 40,
87	  rune: 25,
88	  moonstone: 25,
89	};
90	
91	const BLOCK_SIZE = 3;
92	const BLOCK_BASE_PREMIUM = 60;
93	
94	const countByType = (items: Item[]): Map<string, number> => {
95	  const counts = new Map<string, number>();
96	  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
97	
98	  return counts;
99	};
100	
101	// Priced per GROUP of alike items, not per item: a group of exactly BLOCK_SIZE
102	// buys the flat block rate instead of the unit price. Deliberately not named
103	// after BASE_PREMIUMS[type] — that constant is the unit price, this is the
104	// group's premium, and conflating the two is what the block rule invites.
105	const premiumForAlikeGroup = (type: string, count: number): number =>
106	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
107	
108	const policyBasePremium = (items: Item[]): number =>
109	  sumOf([...countByType(items)], ([type, count]) => premiumForAlikeGroup(type, count));
110	
111	const CURSE_PERCENT = 50;
112	
113	const HIGH_ENCHANTMENT_PERCENT = 30;
114	const HIGH_ENCHANTMENT_THRESHOLD = 5;
115	
116	const itemSurcharge = (item: Item): number => {
117	  const base = BASE_PREMIUMS[item.type];
118	  const curseSurcharge = percentOfWhen(item.cursed === true, base, CURSE_PERCENT);
119	  const highEnchantmentSurcharge = percentOfWhen(
120	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
121	    base,
122	    HIGH_ENCHANTMENT_PERCENT,
123	  );
124	
125	  return curseSurcharge + highEnchantmentSurcharge;
126	};
127	
128	const itemSurcharges = (items: Item[]): number => sumOf(items, itemSurcharge);
129	
130	// Every modifier is a percentage of a base premium, and they are SUMMED rather
131	// than compounded: the spec's worked example reads
132	// "100 G base + 50 G curse + 10 G first insurance = 160 G + 5 G fee = 165 G",
133	// so the first-insurance 10 % is taken on the policy base, not on the
134	// curse-inflated amount.
135	const LOYALTY_PERCENT = 20;
136	const LOYALTY_THRESHOLD_YEARS = 2;
137	
138	const FOLLOW_UP_PERCENT = 15;
139	
140	// Rejections surface as exceptions; the CLI turns them into a non-zero exit
141	// and a stderr line.
142	const rejectUnknownTypes = (items: Item[]): void => {
143	  for (const { type } of items) {
144	    if (!(type in BASE_PREMIUMS)) throw new Error(`The MHPCO does not insure a ${type}.`);
145	  }
146	};
147	
148	const quote = ({ items }: QuoteStep, customer: Customer, isFollowUp: boolean): StepResult => {
149	  rejectUnknownTypes(items);
150	
151	  const policyBase = policyBasePremium(items);
152	
153	  // Surcharges add to the policy base, discounts subtract from it. Both are
154	  // percentages OF THE POLICY BASE (never of each other) — see the note above.
155	  const firstInsuranceSurcharge = percentOf(policyBase, FIRST_INSURANCE_PERCENT);
156	  const loyaltyDiscount = percentOfWhen(
157	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
158	    policyBase,
159	    LOYALTY_PERCENT,
160	  );
161	
162	  const followUpDiscount = percentOfWhen(isFollowUp, policyBase, FOLLOW_UP_PERCENT);
163	
164	  const surcharges = itemSurcharges(items) + firstInsuranceSurcharge;
165	  const discounts = loyaltyDiscount + followUpDiscount;
166	  const total = policyBase + surcharges - discounts + PROCESSING_FEE;
167	
168	  return { premium: roundPremiumInMhpcosFavour(total) };
169	};
170	
171	// ---------------------------------------------------------------------------
172	// Claim side — settling a payout against an open policy.
173	// ---------------------------------------------------------------------------
174	
175	const INSURANCE_VALUES: Record<string, number> = {
176	  sword: 1000,
177	  amulet: 600,
178	  staff: 800,
179	  potion: 400,
180	  rune: 250,
181	  moonstone: 250,
182	};
183	
184	const DEDUCTIBLE = 100;
185	const CAP_MULTIPLIER = 2;
186	
187	interface Policy {
188	  items: Item[];
189	  remainingCap: number;
190	}
191	
192	// The cap is a multiple of the INSURED values of the items — the unit values,
193	// untouched by anything that moved the premium (block rate, curse, loyalty).
194	const insuranceSum = (items: Item[]): number =>
195	  sumOf(items, ({ type }) => INSURANCE_VALUES[type]);
196	
197	const openPolicy = (items: Item[]): Policy => ({
198	  items,
199	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
200	});
201	
202	// Settling a claim both answers the step and moves the policy on: successive
203	// claims draw down the same cap. Rather than writing through the caller's
204	// Policy, `claim` returns the policy it leaves behind, so the depletion is
205	// visible at the one place that owns the registry.
206	// The claim-side enchantment threshold (8) is deliberately NOT the premium-side
207	// one (5): a sword can be enchanted enough to cost more to insure without being
208	// enchanted enough to have its damage halved.
209	const HALVED_REIMBURSEMENT_THRESHOLD = 8;
210	const HALVED_REIMBURSEMENT_PERCENT = 50;
211	
212	// How much of a damage amount the policy covers, BEFORE the deductible — the
213	// caller subtracts that. Special clauses are written as guards in precedence
214	// order: the first one that matches decides, so a clause that must win over
215	// another is simply written above it.
216	const coveredAmount = (damage: Damage, item: Item): number => {
217	  const isHighlyEnchanted = (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_THRESHOLD;
218	  if (isHighlyEnchanted) return percentOf(damage.amount, HALVED_REIMBURSEMENT_PERCENT);
219	
220	  return damage.amount;
221	};
222	
223	// What a single damage entry is worth on its own: the covered amount that the
224	// item's clauses allow, less the deductible that every damaged item carries.
225	const payoutForDamage = (damage: Damage, items: Item[]): number => {
226	  const item = items.find(({ type }) => type === damage.itemType);
227	  if (!item) throw new Error(`This policy does not cover a ${damage.itemType}.`);
228	
229	  return coveredAmount(damage, item) - DEDUCTIBLE;
230	};
231	
232	// The two limits the incident total is squeezed between, named so each call site
233	// says which way it bites rather than leaving the reader to decode a bare
234	// Math.max/Math.min. Both are floors and ceilings on the SAME quantity, applied
235	// in this order: nothing below zero, nothing above what the cap still holds.
236	const neverBelowZero = (amount: number): number => Math.max(0, amount);
237	const neverAboveRemainingCap = (amount: number, remainingCap: number): number =>
238	  Math.min(amount, remainingCap);
239	
240	// Rejected outright rather than left to the payout's zero floor, which would
241	// quietly turn a nonsensical claim into a payout of nothing.
242	const rejectNegativeAmounts = (damages: Damage[]): void => {
243	  for (const { itemType, amount } of damages) {
244	    if (amount < 0) {
245	      throw new Error(`A ${itemType} cannot suffer a negative damage of ${amount} G.`);
246	    }
247	  }
248	};
249	
250	// A policy insuring one sword cannot answer for two damaged swords. The whole
251	// claim is rejected rather than paid in part.
252	const rejectOverCountedDamages = (damages: Damage[], items: Item[]): void => {
253	  const insured = countByType(items);
254	  const claimed = new Map<string, number>();
255	
256	  for (const { itemType } of damages) {
257	    const count = (claimed.get(itemType) ?? 0) + 1;
258	    claimed.set(itemType, count);
259	
260	    if (count > (insured.get(itemType) ?? 0)) {
261	      throw new Error(`This policy does not cover ${count} items of type ${itemType}.`);
262	    }
263	  }
264	};
265	
266	const claim = (
267	  { incident }: ClaimStep,
268	  policy: Policy,
269	): { result: StepResult; policy: Policy } => {
270	  rejectNegativeAmounts(incident.damages);
271	  rejectOverCountedDamages(incident.damages, policy.items);
272	
273	  // Per-damage amounts stay fractional: the rounding wraps the SUMMED total, not
274	  // each entry, and happens before the cap clamp below so remainingCap stays whole.
275	  const incidentTotal = roundPayoutInMhpcosFavour(
276	    sumOf(incident.damages, (damage) => payoutForDamage(damage, policy.items)),
277	  );
278	
279	  // A damage below the deductible pays nothing; the MHPCO is stingy, not a
280	  // debt collector. Only the TOTAL is held at zero — whether a below-deductible
281	  // entry should offset a sibling entry in the same incident is unspecified.
282	  const claimable = neverBelowZero(incidentTotal);
283	
284	  // The policy pays at most what is left of its cap; the excess is simply lost.
285	  const payout = neverAboveRemainingCap(claimable, policy.remainingCap);
286	  const remainingCap = policy.remainingCap - payout;
287	
288	  return { result: { payout, remainingCap }, policy: { ...policy, remainingCap } };
289	};
290	
291	// The follow-up discount is about contract number, so only quote steps count —
292	// interleaved claim steps must not make the next quote look like a follow-up.
293	const isFollowUpQuote = (steps: Step[], index: number): boolean =>
294	  steps.slice(0, index).some((earlier) => earlier.op === "quote");
295	
296	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
297	  // Policies opened by quote steps, keyed by the step index a later claim cites.
298	  // Claims draw the cap down, so this registry is the one piece of carried state.
299	  const policies = new Map<number, Policy>();
300	
301	  const results = steps.map((step, index) => {
302	    if (step.op === "quote") {
303	      policies.set(index, openPolicy(step.items));
304	
305	      return quote(step, customer, isFollowUpQuote(steps, index));
306	    }
307	
308	    const settled = claim(step, policies.get(step.policy) as Policy);
309	    policies.set(step.policy, settled.policy);
310	
311	    return settled.result;
312	  });
313	
314	  return { results };
315	};
