// item's clauses allow, less the deductible that every damaged item carries.
// Takes the already-resolved item rather than finding it: by the time any
// arithmetic runs, `rejectUninsuredDamages` has established that every damage
// resolves, so there is no absent case left for this function to answer for.
const payoutForDamage = (damage: Damage, item: Item): number =>
  coveredAmount(damage, item) - DEDUCTIBLE;

// A policy answers only for what it insures. Hoisted to sit with its sibling
// guards rather than living inside the payout arithmetic: "the whole claim is
// rejected, never partially paid" is a claim-level contract, and keeping all
// four rejections at the top of `claim` is what makes that contract structural
// instead of a consequence of which order the fold happens to visit entries in.
const findInsuredItem = (items: Item[], itemType: string): Item | undefined =>
  items.find(({ type }) => type === itemType);

